import React from 'react';
import { Plus, Trash2, MessageSquare, Loader2 } from 'lucide-react';
import { Button } from './ui/button';
import { cn } from '../lib/utils';
import type { Session } from '../types';
import { format } from 'date-fns';

interface Props {
  sessions: Session[];
  currentSessionId: string | null;
  isLoading: boolean;
  onSelectSession: (sessionId: string) => void;
  onCreateSession: () => void;
  onDeleteSession: (sessionId: string) => void;
  onClose?: () => void;
}

export function HistorySidebar({
  sessions,
  currentSessionId,
  isLoading,
  onSelectSession,
  onCreateSession,
  onDeleteSession,
  onClose,
}: Props) {
  return (
    <div className="w-full lg:w-64 text-sidebar-foreground flex flex-col h-full">
      {/* Header */}
      <div className="px-4 py-3 border-b border-sidebar-border flex items-center gap-2">
        <Button
          onClick={onCreateSession}
          size="icon"
          className="shrink-0 size-9 bg-sidebar-accent hover:bg-sidebar-accent/80 text-sidebar-foreground hover:text-sidebar-foreground transition-all duration-200 hover:scale-[1.02] active:scale-[0.98] cursor-pointer"
          disabled={isLoading}
        >
          <Plus className="h-4 w-4" />
        </Button>
        <span className="font-medium text-sm text-sidebar-foreground">Nuevo chat</span>
      </div>

      {/* Sessions list */}
      <div className="flex-1 overflow-y-auto">
        {isLoading ? (
          <div className="flex items-center justify-center p-4">
            <Loader2 className="h-5 w-5 animate-spin text-sidebar-foreground/50" />
          </div>
        ) : sessions.length === 0 ? (
          <div className="p-4 text-center text-sidebar-foreground/50 text-sm">
            No conversations yet
          </div>
        ) : (
          <div className="px-4 py-3 space-y-1">
            {sessions.map((session) => (
              <div
                key={session.id}
                className={cn(
                  'group flex items-center gap-2 p-2 rounded-lg cursor-pointer transition-all duration-200 hover:scale-[1.01]',
                  currentSessionId === session.id
                    ? 'bg-sidebar-accent shadow-sm'
                    : 'hover:bg-sidebar-accent/50'
                )}
                onClick={() => {
                  onSelectSession(session.id);
                  onClose?.();
                }}
              >
                <MessageSquare className="h-4 w-4 flex-shrink-0 text-sidebar-foreground/70" />
                <div className="flex-1 min-w-0">
                  <p className="text-sm truncate text-sidebar-foreground">
                    {session.title || 'New conversation'}
                  </p>
                  <p className="text-xs text-sidebar-foreground/50">
                    {format(new Date(session.created_at), 'MMM d, yyyy')}
                  </p>
                </div>
                <Button
                  variant="ghost"
                  size="icon"
                  className="h-6 w-6 opacity-100 md:opacity-0 md:group-hover:opacity-100 hover:bg-sidebar-accent/80 transition-all duration-200 hover:scale-110"
                  onClick={(e) => {
                    e.stopPropagation();
                    onDeleteSession(session.id);
                  }}
                >
                  <Trash2 className="h-3 w-3 text-sidebar-foreground/70 hover:text-destructive" />
                </Button>
              </div>
            ))}
          </div>
        )}
      </div>

    </div>
  );
}